from sqlalchemy import Column, Integer, String, DateTime, ForeignKey, Enum, Text, JSON
from sqlalchemy.dialects import mysql
from sqlalchemy.orm import declarative_base
from sqlalchemy.sql import func
from .users import Base
class ContactRevealAudit(Base): __tablename__ = "contact_reveal_audits"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); property_listing_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("property_listings.id", ondelete="SET NULL", onupdate="SET NULL"), nullable=True); revealed_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False)
class ActivityLog(Base): __tablename__ = "activity_logs"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); action = Column(String(100), nullable=False); entity_type = Column(String(50), nullable=True); entity_id = Column(mysql.BIGINT(unsigned=True), nullable=True); details = Column(JSON, nullable=True); created_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False)
class AuditLog(Base): __tablename__ = "audit_logs"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); action = Column(String(100), nullable=False); entity = Column(String(50), nullable=True); before_json = Column(JSON, nullable=True); after_json = Column(JSON, nullable=True); created_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False)